const config = $('Config').item.json;
const raw = $('Ticket entrante').item.json;
const body = raw.body || raw;
return [{ json: {
  model: config.model,
  umbral_confianza: config.umbral_confianza,
  system_prompt: config.system_prompt,
  nombre: body.nombre || 'cliente',
  empresa: body.empresa || '',
  mensaje: body.mensaje || body.text || '',
  canal: body.canal || 'webhook',
  ticket_id: body.ticket_id || ''
} }];

const datos = $('Extraer datos').item.json;
const raw = $json.content?.[0]?.text || '{}';
let d;
try { d = JSON.parse(raw); } catch (e) {
  d = { urgencia: 'media', area: 'otro', sentimiento: 'neutro', resumen: raw.slice(0, 80), confianza: 0.3, requiere_humano: true };
}
const escalar = d.requiere_humano || d.urgencia === 'alta' || d.sentimiento === 'furioso' || d.confianza < datos.umbral_confianza;
const ticketId = datos.ticket_id || 'TKT-' + Date.now();
// Enmascara empresa en log (minima exposicion de datos, Ley 19.628)
const logTag = datos.empresa ? datos.empresa.slice(0, 3) + '***' : 'N/A';
return [{ json: {
  ticket_id: ticketId,
  nombre: datos.nombre,
  empresa_log: logTag,
  canal: datos.canal,
  mensaje_original: datos.mensaje,
  clasificacion: d,
  escalar
} }];
